class Solution {
  public String[] splitMessage(String message, int limit) {
    int n = message.length();
    long digitSum = 0; // total digits of the indices 1..parts
    int parts = 0;
    for (int b = 1; b <= n; b++) {
      digitSum += String.valueOf(b).length();
      int digits = String.valueOf(b).length();
      if (limit - 3 - digits - digits <= 0)
        return new String[0]; // even the last suffix leaves no room
      long capacity = (long) b * (limit - 3 - digits) - digitSum;
      if (capacity >= n) {
        parts = b;
        break;
      }
    }
    if (parts == 0) return new String[0];
    String[] result = new String[parts];
    int at = 0;
    for (int i = 1; i <= parts; i++) {
      String suffix = "<" + i + "/" + parts + ">";
      int take = Math.min(n - at, limit - suffix.length());
      result[i - 1] = message.substring(at, at + take) + suffix;
      at += take;
    }
    return result;
  }
}
